CREATE TABLE cost_centers (cost_center_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, requesting_unit_id TEXT NOT NULL, requesting_unit_name TEXT NOT NULL, manager_person_id TEXT NOT NULL, manager_name TEXT NOT NULL, fund_code TEXT NOT NULL, program_code TEXT NOT NULL, revenue_worktag TEXT NOT NULL, active_status TEXT NOT NULL CHECK (active_status IN ('active','inactive')), effective_start_date TEXT NOT NULL, effective_end_date TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (institution_id, requesting_unit_id, cost_center_id));

CREATE TABLE contract_financial_lines (financial_line_id TEXT PRIMARY KEY, contract_id TEXT NOT NULL, cost_center_id TEXT NOT NULL, source_quote_line_id TEXT NOT NULL, source_quote_record_state TEXT NOT NULL CHECK (source_quote_record_state IN ('current_extract','retired_not_in_current_extract')), fee_category TEXT NOT NULL, line_description TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), amount_usd INTEGER NOT NULL CHECK (amount_usd >= 0) /* whole US dollars */, revenue_worktag TEXT NOT NULL, invoice_schedule TEXT NOT NULL, payment_method TEXT NOT NULL, payment_timeline_days INTEGER NOT NULL CHECK (payment_timeline_days >= 0), service_start_date TEXT NOT NULL, service_end_date TEXT NOT NULL, line_status TEXT NOT NULL CHECK (line_status IN ('finance_coded','ready_to_invoice','on_hold','closed','void')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (cost_center_id) REFERENCES cost_centers(cost_center_id));

CREATE TABLE fiscal_reviews (fiscal_review_id TEXT PRIMARY KEY, contract_id TEXT NOT NULL, cost_center_id TEXT NOT NULL, reviewer_person_id TEXT NOT NULL, reviewer_name TEXT NOT NULL, review_status TEXT NOT NULL CHECK (review_status IN ('pending','approved','approved_with_conditions','additional_pricing_required','rejected','superseded')), funds_certification_status TEXT NOT NULL CHECK (funds_certification_status IN ('not_reviewed','not_certified','certified','not_applicable')), missing_data_reason_code TEXT, missing_data_detail TEXT, missing_source_quote_line_id TEXT, missing_amount_usd INTEGER CHECK (missing_amount_usd IS NULL OR missing_amount_usd >= 0) /* whole US dollars */, decision_conditions TEXT, evidence_reference TEXT, requested_at TEXT NOT NULL, approval_timestamp TEXT, is_current INTEGER NOT NULL CHECK (is_current IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (cost_center_id) REFERENCES cost_centers(cost_center_id));